function notify(message,error=false){$('#toast').textContent=message;$('#toast').className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),error?6500:3400);$('#statusText').innerHTML=`<i></i> ${esc(message)}`;}
