function clipHTML(c,t){const fd=sources.get(c.source);return `<div class="clip ${c.id===selectedClip?'selected':''}" data-clip="${c.id}" data-track="${t.id}" tabindex="0" role="button" aria-label="${esc(c.name)}, inicio ${formatTime(c.start,true)}, duración ${formatTime(c.duration,true)}" style="left:${c.start*zoom}px;width:${Math.max(4,c.duration*zoom)}px;--color:${t.color}" title="${esc(c.name)} · arrastra para mover; extremos para recortar"><div class="clip-label">${icon('wave')}<span>${esc(c.name)}</span></div><canvas></canvas><svg class="fade-line" viewBox="0 0 100 62" preserveAspectRatio="none"><path d="M0 ${c.fadeIn?60:1} L${c.duration?c.fadeIn/c.duration*100:0} 1 L${c.duration?(c.duration-c.fadeOut)/c.duration*100:100} 1 L100 ${c.fadeOut?60:1}"/></svg>${(c.points||[]).map(point=>`<button class="edit-point" data-point="${point}" style="left:${point/c.duration*100}%" aria-label="Punto de edición ${formatTime(c.start+point,true)}" title="Punto de edición · clic derecho para seleccionar un tramo"></button>`).join('')}<div class="clip-range" style="display:${project.region?.clipId===c.id?'block':'none'};left:${project.region?.clipId===c.id?(project.region.start-c.start)/c.duration*100:0}%;width:${project.region?.clipId===c.id?(project.region.end-project.region.start)/c.duration*100:0}%"></div><div class="clip-handle left" data-handle="left" title="Recortar inicio"></div><div class="clip-handle right" data-handle="right" title="Recortar final"></div></div>`;}
function peakCache(buffer){if(waveCache.has(buffer))return waveCache.get(buffer);const data=buffer.getChannelData(0),stride=128,peaks=new Float32Array(Math.ceil(data.length/stride)*2);for(let p=0,i=0;i<data.length;i+=stride,p+=2){let lo=0,hi=0;for(let j=i;j<Math.min(i+stride,data.length);j++){lo=Math.min(lo,data[j]);hi=Math.max(hi,data[j]);}peaks[p]=lo;peaks[p+1]=hi;}const cache={peaks,stride};waveCache.set(buffer,cache);return cache;}
function drawWave(el){const found=findClip(project,el.dataset.clip);if(!found)return;const {clip,track}=found,buffer=sources.get(clip.source);if(!buffer)return;const canvas=el.querySelector('canvas'),width=Math.min(6000,Math.max(4,Math.ceil(clip.duration*zoom))),height=60;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');if(!ctx)return;const {peaks,stride}=peakCache(buffer);ctx.strokeStyle=track.color;ctx.globalAlpha=.9;ctx.lineWidth=1;ctx.beginPath();const gain=Math.min(2,dbGain(clip.gain));for(let x=0;x<width;x+=2){const from=Math.floor((clip.offset+clip.duration*x/width)*buffer.sampleRate/stride),to=Math.min(peaks.length/2,Math.ceil((clip.offset+clip.duration*(x+2)/width)*buffer.sampleRate/stride));let lo=0,hi=0;for(let i=from;i<to;i++){lo=Math.min(lo,peaks[i*2]);hi=Math.max(hi,peaks[i*2+1]);}const level=envelope(clip,clip.duration*x/width)*gain;ctx.moveTo(x,30+lo*27*level);ctx.lineTo(x,30+hi*27*level);}ctx.stroke();ctx.globalAlpha=.25;ctx.beginPath();ctx.moveTo(0,30);ctx.lineTo(width,30);ctx.stroke();}
function updatePlayhead(){const x=trackWidth()+position*zoom;$('#playhead').style.left=x+'px';$('#timeDisplay').textContent=formatTime(position,true);if(recording){const el=$('#recordingClip');if(el){el.style.left=(recording.start*zoom)+'px';el.style.width=Math.max(5,(position-recording.start)*zoom)+'px';}}}
function updateRegion(){const r=project.region;for(const el of $$('.clip-range')){const f=findClip(project,el.closest('.clip').dataset.clip);const active=f&&r?.clipId===f.clip.id;el.style.display=active?'block':'none';if(active){el.style.left=((r.start-f.clip.start)/f.clip.duration*100)+'%';el.style.width=((r.end-r.start)/f.clip.duration*100)+'%';}}$('#region').style.display=r?'block':'none';if(r){$('#region').style.left=(trackWidth()+r.start*zoom)+'px';$('#region').style.width=((r.end-r.start)*zoom)+'px';}}
function select(cid,tid){if(project.region?.clipId&&project.region.clipId!==cid){project.region=null;updateRegion();}selectedClip=cid;selectedTrack=tid;$$('.clip').forEach(el=>el.classList.toggle('selected',el.dataset.clip===cid));$$('.track-row').forEach(el=>el.classList.toggle('selected-track',el.dataset.track===tid));renderInspector();updateCounts();}
function renderInspector(){const found=findClip(project,selectedClip),track=project.tracks.find(t=>t.id===selectedTrack);let html='';if(found){const c=found.clip;html=`<h3>${esc(c.name)}</h3><p class="subtitle">CLIP DE AUDIO · ${esc(found.track.name)}</p><label>Nombre<input data-clip-prop="name" value="${esc(c.name)}"></label><div class="field-row"><label>Inicio (s)<input data-clip-prop="start" type="number" min="0" step="0.1" value="${c.start.toFixed(3)}"></label><label>Duración (s)<input data-clip-prop="duration" type="number" min="0.01" step="0.1" value="${c.duration.toFixed(3)}"></label></div><div class="range-label"><span>Ganancia del clip</span><output>${c.gain.toFixed(1)} dB</output></div><input data-clip-prop="gain" type="range" min="-60" max="24" step="0.5" value="${c.gain}" aria-label="Ganancia del clip"><div class="section-label">FUNDIDOS</div><div class="field-row"><label>Entrada (s)<input data-clip-prop="fadeIn" type="number" min="0" max="${c.duration}" step="0.1" value="${c.fadeIn.toFixed(2)}"></label><label>Salida (s)<input data-clip-prop="fadeOut" type="number" min="0" max="${c.duration}" step="0.1" value="${c.fadeOut.toFixed(2)}"></label></div><button id="normalizeClip" class="small-button">Normalizar clip a −1 dB</button><button id="renameSource" class="small-button">Restaurar audio completo</button>`;}else if(track){html=`<h3>${esc(track.name)}</h3><p class="subtitle">PISTA DE AUDIO</p><p class="inspector-empty">Selecciona un clip para ajustar su inicio, duración, ganancia y fundidos.</p>`;}else html='<p class="inspector-empty">Añade una pista para empezar.</p>';
if(selectedSegment()){const range=selectedSegment();html+=`<div class="segment-inspector"><b>SEGMENTO SELECCIONADO</b><span>${formatTime(range.start,true)} — ${formatTime(range.end,true)}</span><button id="inspectorIsolate" class="small-button">Separar para ajustar volumen y fundidos</button></div>`;}if(track){html+=`<div class="section-label">ECUALIZADOR · PISTA</div>`;for(const [key,label] of [['low','Graves · 200 Hz'],['mid','Medios · 1.5 kHz'],['high','Agudos · 5.5 kHz']])html+=`<div class="range-label"><span>${label}</span><output>${track.eq[key].toFixed(1)} dB</output></div><input data-eq="${key}" type="range" min="-12" max="12" step="0.5" value="${track.eq[key]}" aria-label="${label}">`;html+=`<label class="check-row"><input data-compressor type="checkbox" ${track.compressor?'checked':''}>Compresor de voz</label><button id="resetFX" class="small-button">Restablecer efectos</button>`;}$('#inspectorContent').innerHTML=html;if(selectedSegment())for(const input of $$('#inspectorContent [data-clip-prop],#normalizeClip,#renameSource'))input.disabled=true;}
function renderMixer(){let html=project.tracks.map((t,i)=>`<div class="channel" data-track="${t.id}" style="--color:${t.color}"><div class="channel-title"><span>${esc(t.name)}</span><small>${String(i+1).padStart(2,'0')}</small></div><div class="channel-pan"><span>L</span><input data-action="pan" type="range" min="-1" max="1" step="0.01" value="${t.pan}" aria-label="Panorama de ${esc(t.name)}"><span>R</span></div><div class="channel-body"><div class="fader-wrap"><input class="fader" data-action="volume" type="range" min="-60" max="6" step="0.5" value="${t.volume}" aria-label="Volumen de ${esc(t.name)}"></div><div class="channel-meter" data-meter="${t.id}"><i></i><i></i></div><div class="channel-scale"><span>+6</span><span>0</span><span>−12</span><span>−∞</span></div><div class="channel-buttons"><button data-action="mute" class="${t.mute?'on':''}" title="Silenciar" aria-pressed="${t.mute}">M</button><button data-action="solo" class="${t.solo?'on':''}" title="Solo" aria-pressed="${t.solo}">S</button></div></div><div class="channel-db">${t.volume<=-60?'−∞':t.volume.toFixed(1)} dB <span style="float:right;color:#7f9a86">${t.compressor||Object.values(t.eq).some(v=>v)?'FX ON':'FX —'}</span></div></div>`).join('');html+=`<div class="channel master"><div class="channel-title"><span>MASTER</span><small>ESTÉREO</small></div><div class="channel-pan"><span>Salida de la mezcla</span></div><div class="channel-body"><div class="fader-wrap"><input id="masterVolume" class="fader" type="range" min="-60" max="6" step="0.5" value="${project.master}" aria-label="Volumen maestro"></div><div class="channel-meter" data-meter="master"><i></i><i></i></div><div class="channel-scale"><span>+6</span><span>0</span><span>−12</span><span>−∞</span></div><div class="channel-buttons">${icon('headphones')}</div></div><div class="channel-db" id="masterDB">${project.master<=-60?'−∞':project.master.toFixed(1)} dB</div></div>`;$('#mixerChannels').innerHTML=html;}
async function startPlayback(){if(recordPending||exporting||importing)return;if(!recording&&projectDuration(project)===0){notify('Importa un audio o graba con el micrófono para empezar.');return;}const token=++playToken;try{let end=recording?86400:previewPlan?.end??(loop&&project.region?project.region.end:projectDuration(project));if(position>=end)position=previewPlan?.start??(loop&&project.region?project.region.start:0);await engine.init();if(token!==playToken)return;const started=await engine.play(previewPlan?.project||project,position,end);if(token!==playToken||!started)return;$('#playBtn').innerHTML=icon('pause');status(recording?'Grabando micrófono…':'Reproduciendo la mezcla');}catch(e){notify(e.message,true);}}
function stopPlayback(reset=false){++playToken;if(engine.running)position=engine.time;engine.stop();if(reset)position=0;$('#playBtn').innerHTML=icon('play');updatePlayhead();}
function refreshAudio(){if(engine.running&&!recording){if(previewPlan){try{previewPlan=exportPlan(previewPlan.scope);}catch{previewPlan=null;}}position=engine.time;stopPlayback();startPlayback();}}
function seek(t){if(recording||recordPending||importing||exporting)return;previewPlan=null;const playing=engine.running;stopPlayback();position=Math.max(0,t);updatePlayhead();if(playing)startPlayback();}
async function togglePlay(){if(recording){await stopRecording();return;}if(engine.running)stopPlayback();else await startPlayback();}
function animate(){frame=requestAnimationFrame(animate);if(engine.running){position=engine.time;updatePlayhead();const end=previewPlan?.end??(loop&&project.region?project.region.end:projectDuration(project));if(!recording&&position>=end){if(loop&&end>0){stopPlayback();position=project.region?.start??0;startPlayback();}else{stopPlayback();previewPlan=null;position=end;updatePlayhead();status('Reproducción finalizada');}}if(recording){const expected=trackWidth()+timelineDuration()*zoom;if(parseFloat($('#timeline').style.width)<expected-zoom*4){$('#timeline').style.width=expected+'px';}const sc=$('#arrangeScroll'),x=trackWidth()+position*zoom;if(x-sc.scrollLeft>sc.clientWidth-50)sc.scrollLeft=x-sc.clientWidth+100;}}
for(const el of $$('[data-meter]')){const node=el.dataset.meter==='master'?engine.masterAnalyser:engine.chains.get(el.dataset.meter)?.analyser;const value=engine.running?engine.meter(node):0;for(const bar of el.children)bar.style.height=(value*100)+'%';}const mic=recorder?.analyser?engine.meter(recorder.analyser):0;$('#micLevel i').style.width=(mic*100)+'%';}
async function importAudio(files,targetId=null,at=position){if(recording||recordPending||importing||exporting)return;const list=[...files];if(!list.length)return;importing=true;setRecordUI();document.body.classList.add('busy');stopPlayback();stash();let imported=0;try{const ctx=await engine.init();for(const file of list){status(`Importando ${file.name}…`);try{let buffer=await ctx.decodeAudioData(await file.arrayBuffer());if(buffer.numberOfChannels>2){const mix=new OfflineAudioContext(2,buffer.length,buffer.sampleRate),source=mix.createBufferSource();source.buffer=buffer;source.connect(mix.destination);source.start();buffer=await mix.startRendering();}if(!buffer.duration)throw Error('Audio vacío');let track=targetId?project.tracks.find(t=>t.id===targetId):null;if(!track&&list.length===1)track=project.tracks.find(t=>t.id===selectedTrack);if(!track){track=makeTrack(file.name.replace(/\.[^.]+$/,''),project.tracks.length);project.tracks.push(track);}const sid=id();sources.set(sid,buffer);const c=makeClip(sid,file.name.replace(/\.[^.]+$/,''),buffer.duration,at);track.clips.push(c);selectedTrack=track.id;selectedClip=c.id;imported++;}catch(e){notify(`No se pudo importar «${file.name}». Revisa el formato o el archivo.`,true);}}if(imported){dirty();render();fitZoom();notify(`${imported} ${imported===1?'audio importado':'audios importados'}.`);}else{history.pop();render();}}catch(e){history.pop();notify(e.message,true);}finally{importing=false;setRecordUI();document.body.classList.remove('busy');}}
function fitZoom(){const available=$('#arrangeScroll').clientWidth-trackWidth()-35;zoom=clamp(available/Math.max(10,projectDuration(project)+3),5,200);$('#zoomRange').value=zoom;$('#arrangeScroll').scrollLeft=0;renderTimeline();updatePlayhead();}
function setZoom(value){zoom=clamp(value,5,200);$('#zoomRange').value=zoom;renderTimeline();updatePlayhead();}
async function chooseNew(){if(recording||recordPending||importing||exporting)return;const clips=project.tracks.some(t=>t.clips.length);if(clips&&!await confirmAction('¿Crear un nuevo proyecto?','Guarda una copia si quieres conservar la sesión actual.'))return;stopPlayback(true);stash();previewPlan=null;welcomeDismissed=true;project=makeProject();selectedTrack=project.tracks[0].id;selectedClip=null;loop=false;dirty();render();setZoom(36);notify('Nuevo proyecto preparado.');}
