let contextState=null,draggedTrack=null;
function editingBusy(){return !!recording||recordPending||importing||exporting;}
function hideContextMenu(){const menu=$('#contextMenu');menu.hidden=true;contextState=null;}
function selectedSegment(){const r=project.region,f=findClip(project,selectedClip);return r?.clipId===selectedClip&&f?{...r,track:f.track,clip:f.clip}:null;}
function reconcileSelection(){const r=project.region;if(!r?.clipId)return;const f=findClip(project,r.clipId);if(!f){project.region=null;return;}r.start=Math.max(r.start,f.clip.start);r.end=Math.min(r.end,f.clip.start+f.clip.duration);if(r.end-r.start<.005)project.region=null;}
function chooseSegment(clipId,start,end,newPoint=null){const f=findClip(project,clipId);if(!f)return;const a=clamp(Math.min(start,end),f.clip.start,f.clip.start+f.clip.duration),b=clamp(Math.max(start,end),f.clip.start,f.clip.start+f.clip.duration);if(b-a<.005){notify('Marca un inicio y un final diferentes.');return;}stash();if(newPoint!==null)addClipPoint(project,clipId,newPoint);selectedClip=clipId;selectedTrack=f.track.id;project.region={start:a,end:b,clipId,scope:'clip'};position=a;previewPlan=null;dirty();render();status(`Segmento · ${formatTime(a,true)} — ${formatTime(b,true)}`);}
