function operateSegment(action){if(editingBusy())return;const range=selectedSegment();if(!range){notify('Selecciona primero un segmento entre los puntos.');return;}stash();const result=editClipSegment(project,range.clip.id,range.start,range.end,action);project.region=null;previewPlan=null;selectedClip=result?.id??null;selectedTrack=range.track.id;dirty();render();refreshAudio();status({isolate:'Segmento separado para editar',trim:'Clip recortado al segmento',delete:'Segmento eliminado; los demás clips mantienen su posición',duplicate:'Segmento duplicado',silence:'Segmento silenciado'}[action]);}
function copySegment(cut=false){if(editingBusy())return;const range=selectedSegment();if(!range)return;clipboard=sliceClip(range.clip,range.start,range.end);if(cut)operateSegment('delete');notify(cut?'Segmento cortado. Haz clic derecho para pegarlo.':'Segmento copiado. Haz clic derecho para pegarlo.');}
function pasteSegment(trackId,time){if(editingBusy()||!clipboard)return;if(!sources.has(clipboard.source)){notify('El audio copiado ya no está disponible en esta sesión.',true);return;}const t=project.tracks.find(t=>t.id===trackId);if(!t)return;stash();const c={...clipboard,id:id(),start:Math.max(0,time),points:[...(clipboard.points||[])]};t.clips.push(c);selectedClip=c.id;selectedTrack=t.id;project.region=null;previewPlan=null;dirty();render();refreshAudio();notify('Segmento pegado.');}
