async function auditionSegment(){if(editingBusy())return;try{const p=exportPlan('segment');stopPlayback();previewPlan=p;position=p.start;loop=false;updateCounts();await startPlayback();}catch(e){notify(e.message,true);}}
function addPointAt(clipId,time){if(editingBusy())return;const f=findClip(project,clipId);if(!f)return;stash();if(addClipPoint(project,clipId,time)===null){history.pop();notify('Elige un punto dentro del clip que no esté marcado.');return;}project.region=null;dirty();render();notify(`Punto de edición · ${formatTime(time,true)}`);}
function openAudioMenu(e){const el=e.target.closest('.clip'),lane=e.target.closest('.lane');if(!el&&!lane)return;e.preventDefault();if(editingBusy())return;stopPlayback();previewPlan=null;const f=el?findClip(project,el.dataset.clip):null;const trackId=f?.track.id||lane.dataset.track;let time=el?f.clip.start+(e.clientX-el.getBoundingClientRect().left)/zoom:(e.clientX-lane.getBoundingClientRect().left)/zoom;if(!e.clientX&&!e.clientY)time=position;time=snapped(Math.max(0,time));if(f)time=clamp(time,f.clip.start,f.clip.start+f.clip.duration);const pointElement=e.target.closest('.edit-point');const point=pointElement?Number(pointElement.dataset.point):null;if(point!==null&&f)time=f.clip.start+point;select(f?.clip.id??null,trackId);contextState={clipId:f?.clip.id,trackId,time,point};const r=selectedSegment();const button=(key,label,disabled=false)=>`<button role="menuitem" data-context="${key}" ${disabled?'disabled':''}>${label}</button>`;let html=`<div class="context-title">${formatTime(time,true)}${f?' · '+esc(f.clip.name):' · Pista'}</div>`;if(f){html+=button('point','Añadir punto de edición',point!==null||time<=f.clip.start+.005||time>=f.clip.start+f.clip.duration-.005)+button('remove-point','Eliminar este punto',point===null)+'<div class="context-divider"></div>'+button('select','Seleccionar tramo entre puntos')+button('start','Marcar inicio del segmento')+button('end','Marcar final del segmento')+'<div class="context-divider"></div>'+button('audition','Escuchar segmento',!r)+button('isolate','Separar segmento para editar',!r)+button('trim','Conservar solo el segmento',!r)+button('copy','Copiar segmento',!r)+button('cut','Cortar segmento',!r)+button('duplicate','Duplicar segmento',!r)+button('silence','Silenciar segmento',!r)+button('delete','Eliminar segmento',!r)+button('export','Exportar segmento a MP3 / WAV',!r)+'<div class="context-divider"></div>'+button('split','Dividir clip en este punto');}html+=button('paste','Pegar segmento aquí',!clipboard);const menu=$('#contextMenu');menu.innerHTML=html;menu.hidden=false;menu.style.left=Math.max(5,Math.min(e.clientX,window.innerWidth-260))+'px';menu.style.top=Math.max(5,Math.min(e.clientY,window.innerHeight-menu.offsetHeight-10))+'px';menu.querySelector('button:not(:disabled)')?.focus({preventScroll:true});}
function handleAudioMenu(e){const button=e.target.closest('[data-context]');if(!button||!contextState)return;const c={...contextState},action=button.dataset.context;hideContextMenu();if(action==='point')addPointAt(c.clipId,c.time);else if(action==='remove-point'){stash();removeClipPoint(project,c.clipId,c.point);project.region=null;dirty();render();}else if(action==='select'){const f=findClip(project,c.clipId);const range=clipSegmentAt(f.clip,c.time);chooseSegment(c.clipId,range.start,range.end);}else if(action==='start'||action==='end')markBoundary(action,c.time,c.clipId);else if(['isolate','trim','duplicate','silence','delete'].includes(action))operateSegment(action);else if(action==='copy'||action==='cut')copySegment(action==='cut');else if(action==='paste')pasteSegment(c.trackId,c.time);else if(action==='audition')auditionSegment();else if(action==='export')openExport('segment');else if(action==='split')doSplit(c.time,c.clipId,true);}
function bindTrackReorder(){const root=$('#trackRows');const clear=()=>{$$('.track-row').forEach(row=>row.classList.remove('drop-before','drop-after','dragging-track'));};root.addEventListener('dragstart',e=>{const handle=e.target.closest('.track-drag-handle');if(!handle)return;if(editingBusy()){e.preventDefault();return;}hideContextMenu();draggedTrack=handle.closest('.track-row').dataset.track;e.dataTransfer.setData('application/x-viva-track',draggedTrack);e.dataTransfer.effectAllowed='move';handle.closest('.track-row').classList.add('dragging-track');});root.addEventListener('dragover',e=>{if(!draggedTrack)return;const row=e.target.closest('.track-row');if(!row||row.dataset.track===draggedTrack)return;e.preventDefault();e.dataTransfer.dropEffect='move';clear();const rect=row.getBoundingClientRect(),after=e.clientY>=rect.top+rect.height/2;row.classList.add(after?'drop-after':'drop-before');});root.addEventListener('drop',e=>{if(!draggedTrack)return;e.preventDefault();e.stopPropagation();const row=e.target.closest('.track-row');if(row&&row.dataset.track!==draggedTrack){const rect=row.getBoundingClientRect(),after=e.clientY>=rect.top+rect.height/2;stash();if(moveTrack(project,draggedTrack,row.dataset.track,after)){dirty();render();status('Orden de las pistas actualizado');}else history.pop();}draggedTrack=null;clear();});root.addEventListener('dragend',()=>{draggedTrack=null;clear();});root.addEventListener('keydown',e=>{const handle=e.target.closest('.track-drag-handle');if(!handle||!e.altKey||!['ArrowUp','ArrowDown'].includes(e.key)||editingBusy())return;e.preventDefault();const source=handle.closest('.track-row').dataset.track,index=project.tracks.findIndex(t=>t.id===source),target=project.tracks[index+(e.key==='ArrowUp'?-1:1)];if(!target)return;stash();moveTrack(project,source,target.id,e.key==='ArrowDown');dirty();render();$(`.track-row[data-track="${source}"] .track-drag-handle`)?.focus();});}

function bind(){
audioDevices=new AudioDevices({input:$('#micSelect'),output:$('#outputSelect'),status:$('#deviceStatus'),engine,onMessage:notify});$('#detectDevices').onclick=async()=>{try{$('#detectDevices').disabled=true;await audioDevices.requestPermission();}catch(e){notify(e.name==='NotAllowedError'?'Permite el micrófono para mostrar los nombres de los dispositivos.':e.message,true);}finally{$('#detectDevices').disabled=false;}};$('#authorizeOutput').onclick=async()=>{try{await audioDevices.requestOutput();}catch(e){notify(e.name==='NotAllowedError'?'No se autorizó la salida de audio.':e.message,true);}};$('#authorizeOutput').hidden=!navigator.mediaDevices?.selectAudioOutput;

$('#importBtn').onclick=$('#emptyImport').onclick=()=>$('#audioInput').click();$('#audioInput').onchange=e=>{importAudio(e.target.files);e.target.value='';};$('#addTrackBtn').onclick=()=>{if(recording)return;stash();const t=makeTrack(`Pista ${project.tracks.length+1}`,project.tracks.length);project.tracks.push(t);selectedTrack=t.id;selectedClip=null;dirty();render();};
$('#newBtn').onclick=chooseNew;$('#emptyBlank').onclick=()=>{welcomeDismissed=true;render();status('Proyecto en blanco · importa un audio o empieza a grabar');};$('#recoverSession').onclick=async()=>{if(!recoverySession||editingBusy())return;try{await restoreRaw(recoverySession);notify('Sesión anterior recuperada.');}catch(e){notify(e.message,true);}};$('#trackRows').addEventListener('contextmenu',openAudioMenu);$('#contextMenu').addEventListener('click',handleAudioMenu);document.addEventListener('pointerdown',e=>{if(!e.target.closest('#contextMenu'))hideContextMenu();});bindTrackReorder();$('#demoBtn').onclick=$('#emptyDemo').onclick=()=>loadDemo();$('#saveBtn').onclick=$('#confirmSave').onclick=saveProject;$('#openBtn').onclick=()=>$('#projectInput').click();$('#projectInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(project.tracks.some(t=>t.clips.length)&&!await confirmAction('¿Abrir otro proyecto?','Guarda una copia si quieres conservar la sesión actual.'))return;try{status('Abriendo proyecto…');const raw=await unpackProject(file);await restoreRaw(raw);dirty();notify('Proyecto abierto con todos sus audios.');}catch(err){notify(err.message,true);}};
$('#projectName').onchange=e=>{if(recording)return;stash();project.name=e.target.value.trim()||'Mi sesión';e.target.value=project.name;dirty();};$('#undoBtn').onclick=()=>undo();$('#redoBtn').onclick=()=>undo(true);$('#playBtn').onclick=togglePlay;$('#stopBtn').onclick=async()=>{if(recording)await stopRecording();else stopPlayback();status('Detenido');};$('#rewindBtn').onclick=()=>seek(0);$('#recordBtn').onclick=startRecording;$('#loopBtn').onclick=()=>{if(recording)return;loop=!loop;if(loop&&project.region)seek(project.region.start);updateCounts();};$('#timeBtn').onclick=()=>{const value=prompt('Posición en segundos:',position.toFixed(3));if(value!==null&&Number.isFinite(Number(value)))seek(Number(value));};$('#zoomRange').oninput=e=>setZoom(Number(e.target.value));$('#zoomOut').onclick=()=>setZoom(zoom/1.3);$('#zoomIn').onclick=()=>setZoom(zoom*1.3);$('#fitBtn').onclick=fitZoom;
$('#moveTool').onclick=()=>{tool='move';$('#moveTool').classList.add('active');$('#cutTool').classList.remove('active');};$('#cutTool').onclick=()=>{tool='cut';$('#cutTool').classList.add('active');$('#moveTool').classList.remove('active');};$('#splitBtn').onclick=()=>doSplit();$('#duplicateBtn').onclick=()=>{if(selectedSegment()){operateSegment('duplicate');return;}stash();const c=duplicateClip(project,selectedClip);if(c){selectedClip=c.id;dirty();render();refreshAudio();}};$('#deleteBtn').onclick=deleteSelected;
$('#trackRows').addEventListener('click',e=>{handleTrackAction(e);const row=e.target.closest('.track-row');if(!row)return;if(e.target.closest('.clip')||e.target.closest('button'))return;if(!e.target.closest('input')){select(null,row.dataset.track);if(e.target.closest('.lane')&&!dragging)seek(snapped(Math.max(0,(e.clientX-e.target.closest('.lane').getBoundingClientRect().left)/zoom)));}});$('#trackRows').addEventListener('pointerdown',dragClip);$('#ruler').addEventListener('pointerdown',dragRuler);
for(const sel of ['#trackRows','#mixerChannels']){$(sel).addEventListener('input',trackSlider);$(sel).addEventListener('change',e=>{delete e.target.dataset.history;if(e.target.dataset.action==='name'){const t=project.tracks.find(t=>t.id===e.target.closest('[data-track]')?.dataset.track);if(t){stash();t.name=e.target.value.trim()||'Pista';dirty();render();}}});}$('#mixerChannels').addEventListener('click',handleTrackAction);$('#mixerChannels').addEventListener('input',e=>{if(e.target.id==='masterVolume'){if(!e.target.dataset.history){stash();e.target.dataset.history='1';}project.master=Number(e.target.value);$('#masterDB').textContent=(project.master<=-60?'−∞':project.master.toFixed(1))+' dB';engine.updateMaster(project.master);dirty();}});$('#inspectorContent').addEventListener('input',inspectorInput);$('#inspectorContent').addEventListener('change',inspectorChange);$('#inspectorContent').addEventListener('click',e=>{if(recording)return;if(e.target.id==='inspectorIsolate')operateSegment('isolate');if(e.target.id==='normalizeClip')normalizeClip();if(e.target.id==='renameSource'){const f=findClip(project,selectedClip);if(f){stash();f.clip.start=Math.max(0,f.clip.start-f.clip.offset);f.clip.offset=0;f.clip.duration=sources.get(f.clip.source).duration;dirty();render();refreshAudio();}}if(e.target.id==='resetFX'){const t=project.tracks.find(t=>t.id===selectedTrack);if(t){stash();t.eq={low:0,mid:0,high:0};t.compressor=false;dirty();render();refreshAudio();}}});$('#mixerToggle').onclick=()=>{const collapsed=$('.mixer').classList.toggle('collapsed');$('#mixerToggle').innerHTML=(collapsed?'Expandir':'Contraer')+' '+icon('chevron');};$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('#exportBtn').onclick=openExport;$('#doExport').onclick=performExport;$('#exportScope').onchange=updateExportDuration;$('#exportFormat').onchange=()=>$('#exportBitrate').disabled=$('#exportFormat').value==='wav';$('#exportDialog').addEventListener('close',cancelExport);$('#exportDialog').addEventListener('cancel',cancelExport);
const editor=$('.arrangement');editor.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();editor.classList.add('drag-over');}});editor.addEventListener('dragleave',e=>{if(!editor.contains(e.relatedTarget))editor.classList.remove('drag-over');});editor.addEventListener('drop',e=>{if(!e.dataTransfer.files?.length)return;e.preventDefault();editor.classList.remove('drag-over');const lane=e.target.closest('.lane');importAudio(e.dataTransfer.files,lane?.dataset.track??null,lane?snapped(Math.max(0,(e.clientX-lane.getBoundingClientRect().left)/zoom)):position);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#contextMenu').hidden){hideContextMenu();return;}if(e.target.matches('input,textarea,select')||$('dialog[open]'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return;}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();undo(true);return;}if(mod&&e.key.toLowerCase()==='d'&&selectedClip){e.preventDefault();$('#duplicateBtn').click();return;}if(e.code==='Space'){e.preventDefault();togglePlay();}else if(e.key.toLowerCase()==='r'){e.preventDefault();startRecording();}else if(e.key.toLowerCase()==='s'&&!mod)doSplit();else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();}else if(e.key==='Home'){e.preventDefault();seek(0);}else if(e.key==='Escape'){project.region=null;loop=false;updateRegion();renderInspector();updateCounts();}});
window.addEventListener('resize',()=>{renderTimeline();updatePlayhead();});window.addEventListener('beforeunload',e=>{if(recording||revision!==savedRevision){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&revision!==savedRevision)autoSave();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)enumerateMics();});
}
async function boot(){bind();render();animate();enumerateMics();$('#saveState').textContent='Proyecto en blanco';try{db=await initDatabase();recoverySession=await new Promise((resolve,reject)=>{const req=db.transaction('projects').objectStore('projects').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});$('#recoverSession').hidden=!recoverySession;}catch(e){$('#saveState').textContent='Proyecto en blanco · sin autoguardado';}setRecordUI();}
$('#propertiesBtn').onclick=()=>document.body.classList.toggle('inspector-open');$('#inspectorClose').onclick=()=>document.body.classList.remove('inspector-open');
const observer=new MutationObserver(()=>setRecordUI());observer.observe($('#recordBtn'),{attributes:true,attributeFilter:['class']});
boot();
